cd /var/tmp/loop-bench/runs/8d0f6a46a47c/workspace/target; grep -h "| Status" specs/*/spec.md | sort | uniq -c
python3 - <<'E'
p='src/orchestration/tools/registry.test.ts'
s=open(p).read()
a=s.index("  it('validates a function-valued")
b=s.index("  it('compiles a static")
new="""  it('rejects with the schema current at this call for a function-valued definition', async () => {
    const registry = new ToolRegistry();
    registry.register(
      () => ({
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      }),
      async () => 'sunny'
    );

    const first = await registry.execute('get_weather', {city: 'Berlin'});

    expect(first.result).toContain('location');
  });

  it('validates a function-valued definition against the schema returned for each call', async () => {
    const registry = new ToolRegistry();
    let schema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    registry.register(
      () => ({name: 'get_weather', description: 'Get weather', inputSchema: schema}),
      async () => 'sunny'
    );

    await registry.execute('get_weather', {city: 'Berlin'});
    schema = {type: 'object', properties: {city: {type: 'string'}}, required: ['city']};
    const second = await registry.execute('get_weather', {city: 'Berlin'});

    expect(second.result).toBe('sunny');
  });

"""
open(p,'w').write(s[:a]+new+s[b:])
E
